import sys,json,time, pathlib
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot
ROOT=pathlib.Path('/app/output'); RUNS=pathlib.Path('/app/runs')
MMPIX=227.185/1024
SURFACE=.0202
QUAT=[0.,1.,0.,0.]
class Painter:
 def __init__(self):
  self.r=Robot(); self.obs=self.r.get_obs(cameras=[],video='none')
  self.pos=np.array(self.obs.meta['proprio']['now'][7:10]); self.counter=len(list(RUNS.glob('act_*')))
 def save(self,res,folder):
  res.save(str(folder))
  for c,im in res.last.items(): Image.fromarray(im).save(folder/(c+'.png'))
 def run(self,xyz,note='',cams=['practice_cam'],fps=5):
  xyz=np.asarray(xyz); poses=np.c_[xyz,np.tile(QUAT,(len(xyz),1))]
  for off in range(0,len(poses),160):
   a=poses[off:off+160]; self.counter+=1; folder=RUNS/f'act_{self.counter:04d}';folder.mkdir(exist_ok=True)
   np.save(folder/'actions.npy',a)
   before=self.r.status(); (folder/'before.json').write_text(json.dumps(before))
   try: res=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='frames',video_fps=fps,note=note)
   except Exception:
    print('Service exception; reconnect and inspect before replay.',flush=True)
    print(self.r.wait_ready(),flush=True); raise
   self.save(res,folder); self.pos=np.array(res.meta['proprio']['now'][7:10]);
   print(folder.name,'steps',res.meta.get('control_steps'),'left',res.meta.get('time_left_s'),'pos',self.pos.tolist(),'plan',res.meta.get('plan'),flush=True)
   if res.stopped or res.done: raise RuntimeError('Stopped:'+str(res.meta))
  return res
 def move(self,p,speed=.05,hold=.25,cams=['practice_cam'],note='move'):
  p=np.array(p); n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/speed/.05)))
  xyz=np.linspace(self.pos,p,n+1)[1:]; xyz=np.r_[xyz,np.tile(p,(int(hold/.05),1))]
  return self.run(xyz,note,cams)
 def dip(self):
  self.move([self.pos[0],self.pos[1],.08]); self.move([-.1,.155,.08]); self.move([-.1,.155,.023],speed=.03,hold=.5,cams=['scene_cam','side_cam'],note='dip ink'); self.move([-.1,.155,.08],speed=.03)
 def park(self):
  self.move([self.pos[0],self.pos[1],.08]); return self.move([-.1,.155,.08],cams=['canvas_cam','practice_cam','scene_cam'],note='park and inspect')
 def paper(self,u,v,depth,practice=False):
